    v_topic_id UUID;
BEGIN
    -- Ensure Topic exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Reproductive Pathology', 'reproductive-pathology', 3, 2, 60)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- FEMALE: UTERUS & FALLOPIAN TUBES (81-100)
    (v_topic_id, '81. Acute endometritis is a bacterial infection of the endometrium. What is the most common setting for this to occur?', '["Post-menopause", "Retained products of conception following delivery or miscarriage", "Prolonged use of oral contraceptives", "During the luteal phase of the menstrual cycle"]', 1, 'Retained products of conception (e.g., placental fragments) act as a nidus for ascending infection from the vaginal flora.'),
    (v_topic_id, '82. Chronic endometritis is defined histologically by the presence of which specific inflammatory cell in the endometrium?', '["Neutrophils", "Eosinophils", "Plasma cells", "Macrophages"]', 2, 'Lymphocytes are normally present in the endometrium, so plasma cells are required for the diagnosis of chronic endometritis.'),
    (v_topic_id, '83. A patient presents with abnormal uterine bleeding, pelvic pain, and infertility. Biopsy shows plasma cells in the endometrium. Which of the following is a common cause?', '["Human Papillomavirus", "Chlamydia trachomatis (Pelvic Inflammatory Disease)", "Candida albicans", "Treponema pallidum"]', 1, 'Chronic endometritis is often caused by PID (Chlamydia/Gonorrhea), retained products of conception, or IUDs.'),
    (v_topic_id, '84. Endometrial polyps are benign hyperplastic masses of the endometrium. They can be a side effect of which medication?', '["Oral contraceptives", "Tamoxifen", "Clomiphene", "Raloxifene"]', 1, 'Tamoxifen has anti-estrogenic effects on the breast but has weak PRO-estrogenic effects on the endometrium, promoting polyp formation and hyperplasia.'),
    (v_topic_id, '85. Endometriosis is defined as the presence of endometrial glands and stroma outside the uterine cavity. What is the most common site of involvement?', '["Fallopian tubes", "Myometrium", "Ovary", "Pouch of Douglas"]', 2, 'The ovary is the most common site. Endometriosis here forms "chocolate cysts" (endometriomas) filled with old, dark blood.'),
    (v_topic_id, '86. A classic symptom of endometriosis is severe pain with menstruation. Why does this ectopic tissue cause so much pain?', '["It expands rapidly causing mechanical stretch", "It undergoes cyclic bleeding driven by hormones, irritating surrounding tissues and causing fibrosis", "It secretes massive amounts of prostaglandins", "It invades sensory nerves"]', 1, 'The ectopic tissue responds to ovarian hormones just like the normal endometrium, bleeding during menstruation and causing severe inflammation and adhesions.'),
    (v_topic_id, '87. According to the Retrograde Menstruation Theory (Sampson''s theory), how does endometriosis develop?', '["Metaplasia of the coelomic epithelium", "Lymphatic spread of endometrial cells", "Menstrual blood flows backward through the fallopian tubes into the pelvis", "Hematogenous spread"]', 2, 'Sampson''s theory is the most widely accepted explanation, proposing that viable endometrial cells flow backward during menses and implant on peritoneal surfaces.'),
    (v_topic_id, '88. Endometriosis involving the muscular wall of the uterus is specifically called?', '["Endometrial hyperplasia", "Leiomyoma", "Adenomyosis", "Endometritis"]', 2, 'Adenomyosis is the presence of endometrial glands and stroma deep within the myometrium, presenting with a uniformly enlarged, "boggy," tender uterus and heavy periods.'),
    (v_topic_id, '89. Women with endometriosis have an increased risk of developing which type of cancer, especially at the site of ectopic tissue (like the ovary)?', '["Squamous cell carcinoma", "Clear cell and Endometrioid carcinoma", "Choriocarcinoma", "Mucinous cystadenocarcinoma"]', 1, 'Endometriosis is a known precursor to clear cell and endometrioid carcinomas of the ovary.'),
    (v_topic_id, '90. Endometrial Hyperplasia involves abnormal proliferation of endometrial glands relative to stroma. What is the primary driving force?', '["Unopposed estrogen", "Excess progesterone", "Low estrogen", "Androgen excess"]', 0, 'Unopposed estrogen (e.g., from obesity, PCOS, estrogen replacement therapy without progesterone) drives continuous growth of the endometrium without the shedding phase.'),
    (v_topic_id, '91. What is the most important histological predictor for Endometrial Hyperplasia progressing to Endometrial Carcinoma?', '["Number of glands", "Presence of cellular atypia", "Thickness of the endometrium", "Presence of plasma cells"]', 1, 'Complex hyperplasia with cellular atypia carries the highest risk (about 30%) of progressing to carcinoma.'),
    (v_topic_id, '92. A 60-year-old postmenopausal woman presents with vaginal bleeding. What is the most important initial step?', '["Prescribe hormone replacement therapy", "Endometrial biopsy to rule out endometrial carcinoma", "Pap smear", "Reassurance"]', 1, 'Postmenopausal bleeding is endometrial cancer until proven otherwise.'),
    (v_topic_id, '93. What are the two main types of Endometrial Carcinoma?', '["Squamous and Adenocarcinoma", "Endometrioid (Type I) and Serous (Type II)", "Clear cell and Mucinous", "Small cell and Large cell"]', 1, 'Type I (Endometrioid) is estrogen-driven and arises from hyperplasia. Type II (Serous) is not driven by estrogen, arises in atrophic endometrium, and is highly aggressive.'),
    (v_topic_id, '94. Type II (Serous) Endometrial Carcinoma is characterized histologically by the formation of papillae and?', '["Reinke crystals", "Koilocytes", "Psammoma bodies", "Call-Exner bodies"]', 2, 'Psammoma bodies (concentric calcifications) are classic for serous carcinomas (of the endometrium, ovary, and thyroid) and meningiomas.'),
    (v_topic_id, '95. Which mutation is highly characteristic of the aggressive Type II (Serous) Endometrial Carcinoma?', '["PTEN", "KRAS", "p53", "APC"]', 2, 'p53 mutations are the hallmark of Type II serous carcinoma, occurring in >90% of cases.'),
    (v_topic_id, '96. Which mutation is frequently found in Type I (Endometrioid) Endometrial Carcinoma?', '["p53", "PTEN", "BRCA1", "HER2/neu"]', 1, 'Loss of the PTEN tumor suppressor gene is a very early event in the hyperplasia-carcinoma sequence for Type I tumors.'),
    (v_topic_id, '97. Endometrioid Carcinoma (Type I) most often occurs in which patient demographic?', '["Young women with multiple partners", "Nulliparous, obese, perimenopausal/postmenopausal women", "Thin, elderly postmenopausal women", "Women with early menopause"]', 1, 'Risk factors are related to high estrogen exposure: obesity (adipose converts androgens to estrone), nulliparity, and late menopause.'),
    (v_topic_id, '98. A 30-year-old woman with a history of recurrent miscarriages and pelvic pain is diagnosed with Asherman Syndrome. What is the pathophysiology?', '["Loss of the basalis layer of the endometrium, leading to scarring (synechiae)", "Endometrial hyperplasia from unopposed estrogen", "Presence of endometrial tissue in the myometrium", "Infection with Chlamydia"]', 0, 'Asherman syndrome is severe intrauterine adhesion/scarring typically caused by aggressive D&C (dilation and curettage) that scrapes away the regenerative basalis layer.'),
    (v_topic_id, '99. Acute Salpingitis (inflammation of the fallopian tubes) is a major component of Pelvic Inflammatory Disease (PID). What are the two most common causative organisms?', '["E. coli and Klebsiella", "N. gonorrhoeae and C. trachomatis", "S. aureus and Streptococcus pyogenes", "HSV and HPV"]', 1, 'Gonorrhea and Chlamydia ascend from the cervix to the uterus and tubes. Chlamydia is the most common cause overall.'),
    (v_topic_id, '100. What is a major long-term complication of chronic Salpingitis?', '["Endometrial cancer", "Ectopic pregnancy due to scarring and strictures of the tube", "Ovarian cancer", "Uterine rupture"]', 1, 'Scarring of the fallopian tube blocks the normal transport of the fertilized egg to the uterus, leading to implantation in the tube (ectopic pregnancy) or complete infertility.'),

    -- FEMALE: MYOMETRIAL TUMORS (101-115)
    (v_topic_id, '101. A Leiomyoma (fibroid) is a benign tumor of which tissue?', '["Endometrial stroma", "Smooth muscle of the myometrium", "Skeletal muscle", "Fibrous connective tissue"]', 1, 'Leiomyomas are benign smooth muscle tumors. They are the most common tumor in females.'),
    (v_topic_id, '102. Leiomyomas are estrogen-sensitive. What happens to them during pregnancy and after menopause?', '["Shrink in pregnancy, grow after menopause", "Grow rapidly in pregnancy, shrink after menopause", "Grow in both", "Shrink in both"]', 1, 'High estrogen levels during pregnancy stimulate rapid growth. Dropping estrogen levels after menopause cause them to atrophy and calcify.'),
    (v_topic_id, '103. Grossly, how do Leiomyomas typically appear in the uterus?', '["A single, large, necrotic mass", "Multiple, well-circumscribed, firm, whorled white masses", "A diffuse, boggy enlargement of the entire uterus", "Cystic, fluid-filled structures"]', 1, 'They are almost always multiple and have a classic "whorled" cut surface. A "boggy" diffuse uterus suggests adenomyosis.'),
    (v_topic_id, '104. A patient with a submucosal leiomyoma is most likely to present with which symptom?', '["Severe constipation", "Urinary frequency", "Heavy menstrual bleeding (menorrhagia) and infertility", "No symptoms"]', 2, 'Submucosal fibroids bulge into the uterine cavity, stretching the endometrium and causing severe bleeding. They can also block implantation.'),
    (v_topic_id, '105. Leiomyosarcoma is a malignant smooth muscle tumor of the uterus. True or False: It typically arises from the malignant transformation of a pre-existing Leiomyoma.', '["True", "False, it arises de novo", "True, but only after menopause", "True, but only in nulliparous women"]', 1, 'Leiomyosarcomas arise de novo (newly formed from myometrial stem cells), NOT from benign fibroids.'),
    (v_topic_id, '106. How does Leiomyosarcoma present differently from Leiomyoma?', '["It is typically multiple white whorled masses in a young woman", "It is typically a single, bulky, fleshy mass with areas of hemorrhage and necrosis in a postmenopausal woman", "It secretes hCG", "It causes amenorrhea"]', 1, 'Malignant features include a single large lesion, necrosis, hemorrhage, high mitotic activity, and significant cellular atypia, usually seen post-menopause.'),
    (v_topic_id, '107. Which location of a Leiomyoma is most likely to press on the bladder, causing urinary frequency?', '["Submucosal", "Intramural", "Subserosal (anterior wall)", "Cervical"]', 2, 'Subserosal fibroids grow outward. If on the anterior surface, they press against the bladder. If posterior, they press on the rectum (constipation).'),
    (v_topic_id, '108. A large leiomyoma can outgrow its blood supply during pregnancy, leading to acute severe pain. What is this process called?', '["Malignant transformation", "Red (carneous) degeneration", "Torsion", "Rupture"]', 1, 'Red degeneration occurs when the fibroid outgrows its blood supply, causing ischemic necrosis and hemorrhage within the tumor.'),
    (v_topic_id, '109. Which genetic mutation is commonly found in uterine Leiomyomas?', '["MED12", "BRCA1", "p53", "RB1"]', 0, 'Mutations in MED12 (Mediator complex subunit 12) are found in up to 70% of uterine leiomyomas.'),
    (v_topic_id, '110. A woman presents with secondary dysmenorrhea and an enlarged, asymmetric, "lumpy-bumpy" uterus on physical exam. What is the most likely diagnosis?', '["Adenomyosis", "Leiomyomata (Fibroids)", "Endometrial carcinoma", "Endometritis"]', 1, 'Multiple fibroids cause an irregularly enlarged, asymmetric uterus. Adenomyosis typically causes a globally, symmetrically enlarged, smooth uterus.'),
    (v_topic_id, '111. What is the most common surgical treatment for symptomatic leiomyomas in a woman who desires future fertility?', '["Hysterectomy", "Endometrial ablation", "Myomectomy", "Oophorectomy"]', 2, 'Myomectomy removes only the fibroids, preserving the uterus for future pregnancies.'),
    (v_topic_id, '112. Uterine adenomyosis and leiomyomas can both cause abnormal uterine bleeding. Which symptom is highly characteristic of adenomyosis but less common with isolated fibroids?', '["Painless bleeding", "Severe dysmenorrhea (painful periods)", "Rapid growth during pregnancy", "Urinary retention"]', 1, 'Adenomyosis involves bleeding deep inside the muscle wall during menses, causing severe pain and a globally enlarged, tender "boggy" uterus.'),
    (v_topic_id, '113. A biopsy of a uterine mass shows spindle cells with cigar-shaped nuclei. Mitotic figures are rare, and there is no necrosis. Diagnosis?', '["Leiomyosarcoma", "Leiomyoma", "Endometrial stromal sarcoma", "Carcinosarcoma"]', 1, 'Smooth muscle cells have "cigar-shaped" nuclei. Lack of necrosis and atypia confirm it is a benign leiomyoma.'),
    (v_topic_id, '114. Which medication can be used to temporarily shrink leiomyomas prior to surgery?', '["Clomiphene", "GnRH agonist (continuous)", "Estrogen", "Tamoxifen"]', 1, 'Continuous GnRH agonists (like Leuprolide) suppress the HPG axis, lowering estrogen levels and shrinking the estrogen-dependent fibroid.'),
    (v_topic_id, '115. A malignant Mixed Mullerian Tumor (Carcinosarcoma) of the uterus contains which types of tissue?', '["Both malignant epithelial (carcinoma) and malignant stromal/mesenchymal (sarcoma) components", "Only malignant smooth muscle", "Only malignant glands", "Benign glands and malignant stroma"]', 0, 'It is a highly aggressive biphasic tumor that contains both carcinomatous (e.g., endometrioid) and sarcomatous (e.g., muscle, cartilage, bone) elements.'),

    -- FEMALE: NON-NEOPLASTIC OVARY & PCOS (116-135)
    (v_topic_id, '116. What is the normal physiological function of a Follicular Cyst?', '["It is always pathological", "It is an unruptured Graafian follicle that failed to ovulate", "It secretes massive amounts of testosterone", "It is the source of hCG"]', 1, 'Follicular cysts are the most common ovarian mass in young women. They arise from follicles that fail to rupture during the cycle and usually resolve spontaneously.'),
    (v_topic_id, '117. What type of cells line a Follicular Cyst?', '["Granulosa and theca cells", "Columnar epithelial cells", "Transitional cells", "Squamous cells"]', 0, 'Because it is a follicle, it is lined by granulosa cells (inner) and theca cells (outer).'),
    (v_topic_id, '118. A Corpus Luteum cyst develops after ovulation. Why does it appear yellow grossly?', '["It contains bile", "The granulosa cells become luteinized (filled with cholesterol/lipids) to produce progesterone", "It is filled with pus", "It is filled with old blood"]', 1, 'The corpus luteum uses cholesterol to synthesize progesterone, giving it a bright yellow color.'),
    (v_topic_id, '119. A Corpus Luteum cyst can rupture, causing severe acute abdominal pain. This presentation most closely mimics which life-threatening condition?', '["Appendicitis", "Ectopic pregnancy", "Ovarian torsion", "Pelvic inflammatory disease"]', 1, 'A ruptured hemorrhagic corpus luteum cyst mimics an ectopic pregnancy (sudden pain, blood in the pelvis), but a pregnancy test (hCG) will be negative.'),
    (v_topic_id, '120. Polycystic Ovarian Syndrome (PCOS) is a common endocrine disorder characterized by multiple ovarian cysts. What is the underlying hormonal imbalance?', '["Low LH, High FSH", "High LH, Low FSH (LH:FSH ratio > 2)", "High estrogen only", "Low androgens"]', 1, 'High LH stimulates the theca cells to produce massive amounts of androgens. Low FSH means the granulosa cells cannot convert all the androgens to estrogen, preventing follicle maturation (anovulation).'),
    (v_topic_id, '121. In PCOS, what happens to the excess androgens produced by the ovaries?', '["They are excreted in the urine", "They are converted to estrone in peripheral adipose tissue", "They bind to estrogen receptors directly", "They suppress insulin release"]', 1, 'The androgens enter the blood and are aromatized to estrone in fat tissue. The estrone feeds back to the pituitary, suppressing FSH and keeping LH high.'),
    (v_topic_id, '122. Due to chronic anovulation, women with PCOS lack which hormone in the second half of their cycle?', '["Estrogen", "Testosterone", "Progesterone", "Prolactin"]', 2, 'Without ovulation, a corpus luteum never forms, so progesterone is never produced. This exposes the endometrium to unopposed estrogen.'),
    (v_topic_id, '123. The unopposed estrogen in PCOS puts the patient at significantly increased risk for which cancer?', '["Ovarian cancer", "Cervical cancer", "Endometrial carcinoma", "Vaginal carcinoma"]', 2, 'The constant stimulation without progesterone-induced shedding leads to endometrial hyperplasia and eventually endometrial carcinoma.'),
    (v_topic_id, '124. What are the classic clinical signs of hyperandrogenism in a woman with PCOS?', '["Hirsutism (excess facial/body hair), acne, and male-pattern baldness", "Breast enlargement", "Voice lightening", "Weight loss"]', 0, 'The high testosterone levels cause virilizing features.'),
    (v_topic_id, '125. Patients with PCOS are highly prone to which metabolic disorder?', '["Hyperthyroidism", "Insulin resistance (Type II Diabetes Mellitus)", "Addison disease", "Cushing disease"]', 1, 'Insulin resistance is a core feature of PCOS. High insulin levels actually synergize with LH to drive even more androgen production in the ovary.'),
    (v_topic_id, '126. A patient with PCOS has dark, velvety, thickened skin on her neck and axillae. What is this called, and what does it indicate?', '["Acanthosis nigricans; indicates insulin resistance", "Lichen sclerosus; indicates low estrogen", "Melasma; indicates high progesterone", "Vitiligo; indicates autoimmune disease"]', 0, 'Acanthosis nigricans is a physical marker of severe insulin resistance.'),
    (v_topic_id, '127. Grossly, what do the ovaries look like in classic PCOS?', '["Small and atrophic", "Enlarged bilaterally with a smooth, thickened capsule and multiple subcortical cysts", "Contain a single, massive cyst", "Filled with dark chocolate-like blood"]', 1, 'The multiple stuck/arrested follicles line up under the thickened outer capsule like a "string of pearls" on ultrasound.'),
    (v_topic_id, '128. What is the first-line medical treatment for regulating the menstrual cycle and providing endometrial protection in PCOS?', '["Clomiphene", "Combined Oral Contraceptives (OCPs)", "Metformin", "Spironolactone"]', 1, 'OCPs provide progestin (protecting the endometrium from hyperplasia) and lower LH levels (decreasing androgen production).'),
    (v_topic_id, '129. If a woman with PCOS desires to get pregnant, which medication is often used to induce ovulation?', '["Spironolactone", "Letrozole or Clomiphene citrate", "Progesterone only pill", "Testosterone"]', 1, 'Clomiphene (SERM) blocks estrogen feedback at the hypothalamus, increasing FSH to force follicle maturation. Letrozole (aromatase inhibitor) is now often preferred first-line.'),
    (v_topic_id, '130. Metformin is often prescribed to women with PCOS primarily to?', '["Directly stimulate ovulation", "Reduce insulin resistance", "Block androgen receptors", "Increase FSH levels"]', 1, 'Lowering insulin levels reduces the synergistic drive on the theca cells to make androgens, which can help restore ovulation.'),
    (v_topic_id, '131. Theca-Lutein cysts are often bilateral and multiple. They are driven by massive levels of which hormone?', '["FSH", "hCG", "Estrogen", "Prolactin"]', 1, 'Conditions with extremely high hCG (like a molar pregnancy, choriocarcinoma, or multiple gestation) massively stimulate the theca cells, forming cysts.'),
    (v_topic_id, '132. An endometrioma of the ovary is commonly referred to as a "Chocolate Cyst". What is the "chocolate" material?', '["Old, hemolyzed blood from repeated cyclical bleeding", "Melanin pigment", "Lipid-laden macrophages", "Mucin"]', 0, 'The ectopic endometrial tissue bleeds during every menstrual cycle. The blood gets trapped in the cyst, turns dark brown over time, and resembles chocolate syrup.'),
    (v_topic_id, '133. Ovarian torsion involves twisting of the ovary and fallopian tube around the infundibulopelvic (suspensory) ligament. Which structure within this ligament gets compressed, causing hemorrhagic infarction?', '["Uterine artery", "Ovarian artery and vein", "Round ligament", "Ureter"]', 1, 'The ovarian artery and vein travel inside the suspensory ligament of the ovary. Twisting cuts off venous return first (causing engorgement), followed by arterial blockage.'),
    (v_topic_id, '134. What is the most common predisposing factor for ovarian torsion?', '["Pelvic Inflammatory Disease", "A pre-existing ovarian mass or cyst (>5cm) that creates a fulcrum", "Pregnancy", "Endometriosis"]', 1, 'A heavy, asymmetric mass (like a mature teratoma) makes the ovary top-heavy, predisposing it to twist on its stalk.'),
    (v_topic_id, '135. A 22-year-old female presents with sudden, sharp right lower quadrant pain. Ultrasound shows a 6cm right ovarian cyst and lack of arterial Doppler flow to the ovary. Next step?', '["Antibiotics", "Immediate surgical detorsion", "Pain meds and discharge", "Appendectomy"]', 1, 'Ovarian torsion is a surgical emergency. The ovary must be untwisted quickly to restore blood flow and save the tissue.'),

    -- FEMALE: OVARIAN SURFACE EPITHELIAL NEOPLASMS (136-160)
    (v_topic_id, '136. Ovarian tumors arise from three main cell types: Surface epithelium, Germ cells, and Sex cord-stroma. Which is the most common origin overall?', '["Germ cells", "Sex cord-stroma", "Surface epithelium (Coelomic epithelium)", "Metastasis"]', 2, 'Surface epithelial tumors account for 70% of all ovarian tumors and >90% of malignant ovarian tumors.'),
    (v_topic_id, '137. Why does the risk of surface epithelial ovarian cancer increase with age and nulliparity?', '["More years of unopposed estrogen", "More trauma to the ovarian surface from repeated ovulations", "Higher rates of HPV infection", "Accumulation of androgens"]', 1, 'Every time a follicle ruptures during ovulation, the surface epithelium is damaged and must repair itself. More repairs = more chance for DNA mutation.'),
    (v_topic_id, '138. Which two factors PROTECT against surface epithelial ovarian cancer by decreasing the total number of ovulations?', '["Smoking and alcohol", "Pregnancy (multiparity) and Oral Contraceptives (OCPs)", "Nulliparity and early menarche", "HRT and tamoxifen"]', 1, 'Pregnancy and OCPs suspend the menstrual cycle, giving the ovarian surface a "break" from the trauma of ovulation.'),
    (v_topic_id, '139. A 65-year-old woman presents with abdominal distension and ascites. Imaging shows a large, bilateral cystic ovarian mass. What is the most likely diagnosis?', '["Endometrioma", "Mature cystic teratoma", "Serous Cystadenocarcinoma", "Fibroma"]', 2, 'Surface epithelial cancers present late (often with ascites/"omental caking") because they have plenty of room to grow in the pelvis before causing symptoms. Serous cystadenocarcinoma is the most common malignant type.'),
    (v_topic_id, '140. Serous cystadenoma is a benign tumor. What type of cells line its cysts?', '["Mucin-secreting cells", "Ciliated columnar cells (resembling fallopian tube epithelium)", "Transitional cells", "Squamous cells"]', 1, 'The surface coelomic epithelium can undergo metaplasia into fallopian tube-like cells (serous), endocervical-like cells (mucinous), or endometrial-like cells (endometrioid).'),
    (v_topic_id, '141. Mucinous cystadenoma is lined by?', '["Ciliated columnar cells", "Mucin-secreting columnar cells (resembling endocervix or intestine)", "Squamous cells", "Urothelium"]', 1, 'They are filled with thick, sticky mucin and can grow to massive sizes (e.g., 50 pounds!).'),
    (v_topic_id, '142. What is the key gross/histological difference between a benign cystadenoma and a malignant cystadenocarcinoma?', '["Cystadenomas are solid, carcinomas are cystic", "Cystadenomas have a smooth inner lining; carcinomas have thick, complex, shaggy solid papillary growths extending into the cyst", "Carcinomas are always unilateral", "Cystadenomas secrete hormones"]', 1, 'Malignant epithelial tumors form complex, invasive papillary structures and show severe nuclear atypia.'),
    (v_topic_id, '143. Which calcified structure is frequently seen on histology in Serous Cystadenocarcinoma?', '["Reinke crystals", "Psammoma bodies", "Schiller-Duval bodies", "Call-Exner bodies"]', 1, 'Psammoma bodies (concentric laminated calcifications) form when the tips of the complex papillae outgrow their blood supply, undergo necrosis, and calcify.'),
    (v_topic_id, '144. Which tumor marker is used to monitor response to therapy and detect recurrence of ovarian surface epithelial carcinomas?', '["hCG", "AFP", "CA-125", "CEA"]', 2, 'CA-125 is elevated in most serous and mucinous carcinomas. It is not a good screening tool (too many false positives), but excellent for monitoring known disease.'),
    (v_topic_id, '145. Women with mutations in which genes have a massively increased risk of both breast and serous ovarian carcinoma?', '["PTEN", "BRCA1 and BRCA2", "p53", "APC"]', 1, 'BRCA1 mutations carry a high risk (up to 40%) of developing ovarian cancer. Prophylactic salpingo-oophorectomy is often recommended.'),
    (v_topic_id, '146. A Mucinous Cystadenocarcinoma of the ovary can sometimes rupture and seed the entire peritoneal cavity with mucin-secreting tumor cells, causing the abdomen to fill with massive amounts of jelly. This condition is called?', '["Ascites", "Meigs Syndrome", "Pseudomyxoma peritonei", "Peritonitis"]', 2, 'Pseudomyxoma peritonei ("jelly belly"). Interestingly, the most common primary source is actually an appendiceal mucinous tumor that metastasized to the ovary, not a primary ovarian tumor.'),
    (v_topic_id, '147. Endometrioid Carcinoma of the ovary is an epithelial tumor that resembles the endometrium. It is uniquely associated with what other condition?', '["Breast cancer", "Endometriosis and concurrent Endometrial Carcinoma (in 15-30% of cases)", "Cervical cancer", "PCOS"]', 1, 'It can arise directly from endometriosis. Many patients have an independent, separate primary endometrial carcinoma at the same time.'),
    (v_topic_id, '148. Clear Cell Carcinoma of the ovary is a variant of endometrioid carcinoma. What is the histological hallmark?', '["Large cells with clear cytoplasm (glycogen) and ''hobnail'' cells sticking out into the glands", "Fried egg cells", "Signet ring cells", "Spindle cells"]', 0, 'Hobnail cells (nuclei protruding into the lumen) and clear cytoplasm are characteristic. It is often associated with endometriosis.'),
    (v_topic_id, '149. A Brenner Tumor is a rare surface epithelial tumor. It is defined by nests of which type of epithelium in a dense fibrous stroma?', '["Squamous", "Ciliated columnar", "Transitional epithelium (resembling the bladder/urothelium)", "Mucinous"]', 2, 'Brenner tumors are usually benign and grossly look pale yellow/tan due to the dense fibrous stroma ("Brenner = Bladder").'),
    (v_topic_id, '150. A 20-year-old female is found to have an ovarian mass. Is this more likely to be a surface epithelial tumor or a germ cell tumor?', '["Surface epithelial tumor", "Germ cell tumor", "Metastasis", "Sex cord-stromal tumor"]', 1, 'While epithelial tumors dominate in older women (50+), Germ Cell Tumors are the most common type of ovarian mass in women under 30.'),
    (v_topic_id, '151. What is the most common GERM CELL tumor in females?', '["Dysgerminoma", "Mature cystic teratoma (Dermoid cyst)", "Yolk sac tumor", "Choriocarcinoma"]', 1, 'Mature cystic teratoma is a benign tumor composed of tissues from >1 embryonic germ layer (e.g., skin, hair, bone, teeth).'),
    (v_topic_id, '152. True or False: A mature cystic teratoma is completely benign.', '["True, always", "False, it is always malignant", "Usually benign, but can undergo malignant transformation (most commonly to Squamous Cell Carcinoma of the skin elements)", "Benign only if it contains teeth"]', 2, 'In about 1% of cases, the mature tissue undergoes somatic malignant transformation (usually SCC arising from the epidermis).'),
    (v_topic_id, '153. A Struma Ovarii is a specialized teratoma composed entirely of which functional tissue?', '["Brain tissue", "Mature thyroid tissue", "Liver tissue", "Adrenal tissue"]', 1, 'It contains functional thyroid tissue and can actually present clinically with hyperthyroidism (thyrotoxicosis).'),
    (v_topic_id, '154. An Immature Teratoma is malignant and aggressive. It is diagnosed by the presence of?', '["Hair and teeth", "Immature, embryonic-like neural tissue (neuroepithelium)", "Schiller-Duval bodies", "Reinke crystals"]', 1, 'The presence of immature neural rosettes dictates the grade and malignant potential of the tumor.'),
    (v_topic_id, '155. What is the female counterpart to the male Seminoma?', '["Yolk sac tumor", "Dysgerminoma", "Choriocarcinoma", "Embryonal carcinoma"]', 1, 'Dysgerminoma is the most common malignant germ cell tumor in females. Like seminoma, it has "fried egg" cells, a lymphocytic infiltrate, and is highly sensitive to radiation.'),
    (v_topic_id, '156. Which serum marker is classically elevated in a Dysgerminoma?', '["LDH (Lactate Dehydrogenase) and hCG", "AFP", "CA-125", "Estrogen"]', 0, 'LDH is a key marker. Some may also secrete small amounts of hCG.'),
    (v_topic_id, '157. A 4-year-old girl presents with an ovarian mass. AFP is massively elevated. Histology shows Schiller-Duval bodies. Diagnosis?', '["Dysgerminoma", "Yolk sac (Endodermal sinus) tumor", "Choriocarcinoma", "Teratoma"]', 1, 'Just like in males, yolk sac tumors are the most common germ cell tumor in children. Schiller-Duval bodies (glomeruloid structures) are pathognomonic.'),
    (v_topic_id, '158. Choriocarcinoma is a highly malignant germ cell tumor of trophoblasts. Why does it metastasize so early and rapidly via the blood?', '["It has no capsule", "Trophoblasts are biologically programmed to invade blood vessels (like they do in a normal placenta)", "It expresses high levels of VEGF", "It moves through lymphatics"]', 1, 'Normal syncytiotrophoblasts invade maternal blood vessels to establish the placenta. The tumor cells do the same, causing early hematogenous spread to the lungs.'),
    (v_topic_id, '159. A patient with an ovarian mass presents with severe hyperthyroidism. Her hCG levels are >100,000 mIU/mL. The tumor is composed of syncytiotrophoblasts and cytotrophoblasts but lacks chorionic villi. Diagnosis?', '["Dysgerminoma", "Yolk sac tumor", "Non-gestational Choriocarcinoma", "Teratoma"]', 2, 'Non-gestational choriocarcinoma arises from a germ cell in the ovary. It has a significantly worse prognosis than gestational choriocarcinoma (which arises from a pregnancy).'),
    (v_topic_id, '160. Why does Choriocarcinoma respond poorly to chemotherapy if it arises spontaneously from an ovarian germ cell, compared to one that arises after a molar pregnancy?', '["It is resistant to all drugs", "Gestational tumors contain paternal DNA, making them immunogenic (foreign) to the mother. Non-gestational tumors are 100% maternal DNA.", "Ovarian blood supply is worse", "It lacks hCG receptors"]', 1, 'Because gestational choriocarcinoma has "foreign" paternal antigens, the mother''s immune system helps fight it, leading to a near 100% cure rate with chemo. Non-gestational is "self" and hides from the immune system.');

